#include "KS/SRC/stringx.h"

class PanelAnim;
class PanelGeom;
class PanelQuad;

class matrix4x4 {
    float values[16] __attribute__((aligned(16)));
};

struct nglQuadVertex {
    float X;
    float Y;
    float U;
    float V;
    unsigned int Color;
};

struct nglTexture;

struct nglQuad {
    nglQuadVertex Verts[4];
    float Z;
    unsigned int MapFlags;
    unsigned int BlendMode;
    unsigned int BlendModeConstant;
    nglTexture *Tex;
};

struct recti {
    int x0;
    int y0;
    int x1;
    int y1;
};

class PanelFile {
    int slide_state;
    float slide_offset;
    float slide_timer;
    float slide_max_time;
    stringx filename;

public:
    PanelGeom *obs;
    stringx path;
    PanelFile *next;
    PanelQuad *pquads;

    virtual ~PanelFile();
    virtual PanelGeom *FindObject(const stringx &search_name);
    virtual PanelGeom *FindObject(const char *search_name);
    virtual PanelQuad *FindQuad(const stringx &search_name);
    PanelQuad *GetPointer(const char *search_name);
};

class PanelQuad {
protected:
    bool isAnim;
    int fade;
    float fade_alpha;
    float fade_timer;
    float mask;
    int maskType;
    PanelAnim *anim;
    nglQuad quad;
    bool drawOn;
    int rotate;
    float rotation;
    float rotate_x;
    float rotate_y;
    int layer;
    float r;
    float g;
    float b;
    float a;
    float x1;
    float y1;
    float x2;
    float y2;
    float width;
    float height;
    float width_a;
    float height_a;
    matrix4x4 matrix;
    bool on_menu;
    bool clip;
    recti clipping;

public:
    matrix4x4 Xform;
    stringx name;
    bool dont_draw;
    float z;
    float u1;
    float v1;
    float u2;
    float v2;
    PanelQuad *next;

    virtual ~PanelQuad();
    virtual void Init(
        float x1, float y1, float x2, float y2,
        float r, float g, float b, float a,
        float u1, float v1, float u2, float v2,
        float z, matrix4x4 object_matrix);
    virtual void TurnOn(bool enabled);
};

class IGOWidget {
protected:
    bool display;

public:
    virtual ~IGOWidget();
    virtual void SetDisplay(bool enabled = true);
    virtual void Update(float time_inc);
    virtual void Draw();
    virtual bool GetDisplay() const;
};

class SpecialMeter {
public:
    void SetFillage(float fillage);
};

class SpecialMeterWidget : public IGOWidget {
private:
    SpecialMeter *meter;
    PanelQuad *bgPQ;
    PanelQuad *colorPQ;
    PanelQuad *fgPQ;
    int flashDir;
    float flashAmt;

public:
    virtual ~SpecialMeterWidget();
    virtual void SetDisplay(bool display = true);
    virtual void Init(PanelFile &panel, SpecialMeter *specialMeter);
    virtual void Update(float time_inc);
    virtual void Draw();
    virtual void SetFillage(float amount);
};

extern const char special_meter_background[];
extern const char special_meter_color[];
extern const char special_meter_foreground[];

__asm__(".equ SetFillage__12SpecialMeterf, 0x00251028");
__asm__(".equ GetPointer__9PanelFilePCc, 0x00152F88");
__asm__(".equ special_meter_background, 0x004C0B28");
__asm__(".equ special_meter_color, 0x004C0B40");
__asm__(".equ special_meter_foreground, 0x004C0B58");

void SpecialMeterWidget::Init(PanelFile & panel, SpecialMeter * specialMeter)
{
	meter = specialMeter;
	meter->SetFillage(0.0f);

	bgPQ = panel.GetPointer(special_meter_background);
	colorPQ = panel.GetPointer(special_meter_color);
	fgPQ = panel.GetPointer(special_meter_foreground);
	bgPQ->TurnOn(true);
	colorPQ->TurnOn(true);
	fgPQ->TurnOn(true);

	SetDisplay(true);

	flashDir = 1;
	flashAmt = 1.0f;
}
